// Fileless sound (#46): an arpeggio of sine tones generated by the engine's mixer. No
// window or GPU: only AudioModule. Plays for ~2 seconds and exits (silent with SDL_AUDIODRIVER=dummy).
#include <mge/mge.h>

#include <array>
#include <chrono>
#include <thread>

namespace {
    class ToneApp : public mge::Application {
    public:
        ToneApp() : mge::Application(mge::ApplicationConfig{}) { addModule<mge::AudioModule>(); }

    protected:
        bool onInit() override {
            m_audio = getModule<mge::AudioModule>();
            MGE_LOG_INFO("Tone", "C major arpeggio generated in code (", m_audio->mixer().sampleRate(),
                         " Hz)");
            return true;
        }

        void onUpdate(float /*dt*/) override {
            // C, E, G, high C: one note every 0.25 s, left to right, then the full chord at the end
            constexpr std::array<float, 4> kNotes = {261.63f, 329.63f, 392.0f, 523.25f};
            m_elapsed += time().unscaledDelta();
            while (m_next < kNotes.size() && m_elapsed >= 0.25f * float(m_next)) {
                const float pan = -0.6f + 0.4f * float(m_next);
                m_audio->playTone({kNotes[m_next], 0.3f, 0.35f, pan});
                m_next++;
            }
            if (m_next == kNotes.size() && !m_chord && m_elapsed >= 1.1f) {
                for (float note : kNotes) m_audio->playTone({note, 0.8f, 0.15f, 0.0f});
                m_chord = true;
            }
            if (m_elapsed >= 2.0f) requestStop();
            // Without a window the loop does not wait for vsync: avoid burning a full CPU core
            std::this_thread::sleep_for(std::chrono::milliseconds(2));
        }

    private:
        mge::AudioModule* m_audio = nullptr;
        float m_elapsed = 0.0f;
        std::size_t m_next = 0;
        bool m_chord = false;
    };
}

mge::Application* mge::createApplication() {
    return new ToneApp();
}
